import{_ as e,o as r,c as i,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Панель и модерация","description":"","frontmatter":{"pageId":"admins/administration","contentRevision":5},"headers":[],"relativePath":"ru/admins/administration.md","filePath":"ru/admins/administration.md"}'),o={name:"ru/admins/administration.md"};function l(n,a,s,d,c,h){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="панель-и-модерация" tabindex="-1">Панель и модерация <a class="header-anchor" href="#панель-и-модерация" aria-label="Permalink to &quot;Панель и модерация&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Открой HTTPS /admin/ и войди legacy Admin:ApiToken. Панель показывает игроков, состояние, экономику, рейды и журнал действий. Для интеграций используй API с отдельным токеном, а не копию cookie.</p><p>Начинай с чтения player/status/actions и уточнения id. Kick разрывает сессию; mute ограничивает чат; ban запрещает вход; economy freeze и raids freeze управляют отдельными подсистемами. Причину фиксируй в аудите.</p><p>Rollback выбирает конкретную версию сейва; reset создаёт новую линию колонии и очищает связанные разрешения. Archive сохраняет колонию отдельно, restore-colony восстанавливает архив при проверке контекста. Coop rollback очищает назначения пешек; отзыв членства завершает сессию. Для влияния администратор может отозвать публикацию с ожидаемой версией, но не включить за игрока.</p><h2 id="moderation-case" tabindex="-1">Разобрать обращение о пропавшей отправке <a class="header-anchor" href="#moderation-case" aria-label="Permalink to &quot;Разобрать обращение о пропавшей отправке {#moderation-case}&quot;">​</a></h2><p>Найди игрока по точному имени/#id, открой карточку и сверяй постоянные id, не только отображаемое имя. Сопоставь время обращения с actions, посылками, лотами/сделками и списанием кошелька. Узнай, завершился ли клиентский snapshot/replay. При доступе с read-токеном часть личных полей скрыта; отсутствие данных в нём не равно отсутствию аккаунта.</p><p>Сначала чтение, потом одна подходящая операция с причиной: отмена сделки, возврат лота/посылки или модерационное действие. Подтверди её результат и доставку. Не делай одновременно rollback колонии и ручную компенсацию без понимания серверной экономики.</p><h2 id="admin-danger" tabindex="-1">Выбор между rollback, reset и archive <a class="header-anchor" href="#admin-danger" aria-label="Permalink to &quot;Выбор между rollback, reset и archive {#admin-danger}&quot;">​</a></h2><p>Rollback выбирает прошлую версию одной карты и повышает write epoch. Reset начинает новую жизнь колонии и отзывает связанные разрешения. Archive освобождает место offline-колонии с отдельной записью; restore-colony требует доступного tile и целого архива. Recreateworld — не средство ремонта одной пешки.</p><p>До опасного действия получи подтверждение, согласованный backup и план уведомления игрока. После rollback попроси выйти в меню/войти заново, после reset — не загружать отделённый старый сейв. Серверное состояние, уже полученное другими игроками, не откатывается только потому, что вернулась старая карта.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Reset, rollback, recreateworld и restore имеют разрушительные последствия: сначала подтверждение и проверенная резервная копия. Не компенсируй сбой простым wallet +n до проверки эскроу. Размораживание не исправляет повреждённый сейв.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./cli">Справочник CLI</a></li><li><a href="./api">Справочник REST API</a></li><li><a href="./backup-recovery">Резервные копии и восстановление</a></li></ul>',16)])])}const u=e(o,[["render",l]]);export{p as __pageData,u as default};
